 * @hidden N
*/
scwin.elwExcelUpload = function () {
    /* sdd-asis-lifecycle:begin fn_ElwExcelUpload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.subcomExcelForm || { elements: [] });
    if ($c.util.getComponent('upd_attachFile').getValue() == null || ($c.util.getComponent('upd_attachFile').getValue() == null ? '' : String($c.util.getComponent('upd_attachFile').getValue())) === '') {
        return;
    } else {
        if (!scwin.checkFileType($c.util.getComponent('upd_attachFile').getValue())) {
            scwin.alertExcel("엑셀 파일만(xls) 업로드 가능합니다.");
            $("#upd_attachFile").replaceWith($("#upd_attachFile").clone(true));
            return;
        }
    }
    let statNm = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ipt_pageGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ipt_pageGubun"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ipt_pageGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ipt_pageGubun")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ipt_pageGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ipt_pageGubun"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "ipt_pageGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ipt_pageGubun")))));
    if (statNm === "subcom") {
        statNm = "자회사현황";
    } else {
        statNm = "종속회사현황";
    }
    scwin.confirmExcel(statNm + "을 업로드 하시겠습니까?");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkFileType
 * @author Inswave
 * @date 2026. 09. 29
 * @param filePath
 * @returns
 * @hidden N
*/
scwin.checkFileType = function (filePath) {
    /* sdd-asis-lifecycle:begin checkFileType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (filePath == null || filePath === "") {
        return false;
    }
    const tfp = filePath.toLowerCase();
    if (tfp.indexOf(".xls") < 0 || tfp.substr(tfp.length - 4, 4) !== ".xls") {
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


